const _wh = $('Webhook Infra').first().json || {};
const d = _wh.body || _wh;
const t = $('Tools Infra').first().json || {};
const findings = [];

const n1 = t.nodo1 || {};
const n2 = t.nodo2 || {};
const nfs = t.nfs_node2_storage || {};
const ram2 = (n2.metrics || {}).ram || {};
if (n1.up !== true) findings.push({level:'CRIT', text:'Nodo 1 no responde'});
if (n2.up !== true) findings.push({level:'CRIT', text:'Nodo 2 no responde'});
if ((n1.ssd || {}).used_pct >= 92) findings.push({level:'CRIT', text:'Disco Nodo 1 al ' + n1.ssd.used_pct + '%'});
else if ((n1.ssd || {}).used_pct >= 86) findings.push({level:'WARN', text:'Disco Nodo 1 al ' + n1.ssd.used_pct + '%'});
if ((ram2.used_pct || 0) >= 85) findings.push({level:'WARN', text:'RAM Nodo 2 al ' + ram2.used_pct + '%'});
if (nfs.status && nfs.status !== 'ok') findings.push({level:'WARN', text:'NFS /mnt/node2-storage ' + nfs.status});
const stopped = (t.node2_containers || []).filter(c => c.status && !/^Up/.test(c.status));
if (stopped.length) findings.push({level:'WARN', text:'Contenedores Nodo 2 no activos: ' + stopped.map(c=>c.name).join(', ')});
if (!findings.length) findings.push({level:'OK', text:'Ambos nodos y el almacenamiento compartido están sanos'});

const severity = findings.some(f => f.level === 'CRIT') ? 'CRIT'
  : findings.length ? 'WARN' : 'OK';
const evidence = JSON.stringify({nodo1:t.nodo1, nodo2:t.nodo2, nfs:t.nfs_node2_storage, containers:t.node2_containers}).slice(0, 4500);
const prompt = `Eres Agent-Infra, empleado especializado de HomeLab Corp.
Tu jefe es HomeLab-Director. Analiza esta evidencia en tiempo real y entrega un
informe ejecutivo de 3 a 5 líneas en español, con hallazgos concretos y
recomendaciones de solo lectura. No reinicies nada, no borres nada, no expongas
secretos. Si no hay problemas, dilo explícitamente.

EVIDENCIA:
${evidence}

HALLAZGOS DETERMINISTAS:
${JSON.stringify(findings)}
`;
return [{json: {
  employee: 'Agent-Infra',
  severity,
  quality_score: 0.9,
  findings,
  evidence,
  prompt,
  directive: d.directive || '',
  task_id: d.task_id || null,
  round_id: d.round_id || null,
  tool_data: t
}}];

const a = $('Analizar Infra').first().json || {};
const l = $('LLM Infra').first().json || {};
const choices = l.choices || [];
const text = ((choices[0] && choices[0].message && choices[0].message.content) || '').trim();
return [{json: {
  employee: a.employee,
  severity: a.severity,
  quality_score: a.quality_score,
  summary: (text || a.summary || 'Sin hallazgos').slice(0, 2500),
  findings: a.findings || [],
  evidence: a.evidence || '',
  directive: a.directive || '',
  task_id: a.task_id || null,
  round_id: a.round_id || null
}}];

const r = $('Rendir cuentas Infra').first().json || {};
const d = $('Redactar informe Infra').first().json || {};
return [{json: {...d, report_id: r.report_id || null, ledger_ok: !!r.ok}}];
